const D = { scale:1, n:8, energy:.6, hue:30, speed:1, density:.35, gap:.5, stomp:.6, x:.5, y:.74, seed:0, species:'mix', style:'storybook', act:'parade' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const TAU = 6.28318530718, PI = Math.PI;
const u = Math.min(width, height);
const N = Math.max(1, Math.round(P.n));
let bt = K.beat * P.speed;
if (S.lastBeat == null || bt < S.lastBeat) S.lastBeat = bt;
S.lastBeat = bt;
S.rms = (S.rms||0)*.85 + (A.rms||0)*.15;
S.bass = (S.bass||0)*.8 + (A.bass||0)*.2;
S.tre = (S.tre||0)*.8 + (A.treble||0)*.2;

const eAmp = (.4 + .6*P.energy) * (.6 + .5*K.intensity);
const kick = Math.min(1, K.pulse*(.5 + .5*K.intensity) + S.bass*.75);

const styles = ['storybook','woodcut','silhouette','chalk','riso'];
const st = styles.indexOf(P.style) >= 0 ? P.style : 'storybook';
const chalk = st === 'chalk';
const sil = st === 'silhouette';
const wood = st === 'woodcut';

const SPECIES = ['duck','dog','cat','elephant'];
function speciesFor(i){
  if (P.species !== 'mix' && SPECIES.indexOf(P.species) >= 0) return P.species;
  if (P.species === 'farm') return ['duck','dog','cat','duck'][((Math.floor(fr(i+2)*4))%4+4)%4];
  return SPECIES[((Math.floor(fr(i+2)*4))%4+4)%4];
}

// species muted-gouache palette hues (offset from P.hue for variety)
function hueFor(sp, i){
  const j = ((P.hue%360)+360)%360;
  const map = { duck: 44, dog: 24, cat: 14, elephant: 210 };
  return ( (map[sp]||j) + (j-30)*0.5 + (fr(i+40)-0.5)*16 + 360 ) % 360;
}

// ---- act dramaturgy ----
const ACT = P.act;
let marchRate, stompBias;
if (ACT === 'stampede') { marchRate = .04*P.speed*(.7+K.intensity); stompBias = P.stomp*1.3; }
else if (ACT === 'amble') { marchRate = .015*P.speed*(.5+K.intensity); stompBias = P.stomp*0.6; }
else { marchRate = .024*P.speed*(.55+.6*K.intensity); stompBias = P.stomp; }
const globalScroll = bt*marchRate + K.t*P.speed*.011;

const M = u*0.2;
const spanW = width + 2*M;

// collective stomp: whole herd dips on the beat
const stompDip = kick * stompBias;

// ---- textured ground band (cached buffer, muted paper) ----
if (S.gKey !== (width+'x'+height+st+((P.hue%360)|0))){
  S.gKey = width+'x'+height+st+((P.hue%360)|0);
  const gy0 = Math.round(P.y*height + u*0.02);
  const gh = Math.max(2, height - gy0);
  const g = createGraphics(width, gh);
  g.colorMode(HSB,360,100,100,100); g.noStroke(); g.clear();
  const gj = ((P.hue%360)+360)%360;
  if (sil){ g.fill(gj,30,12); g.rect(0,0,width,gh); }
  else if (chalk){ g.fill(gj,14,10); g.rect(0,0,width,gh); }
  else {
    const base = wood ? [gj,20,26] : st==='riso' ? [42,20,84] : [38,26,70];
    for (let y=0;y<gh;y+=2){ const t=y/gh; g.fill(base[0], base[1], base[2]*(1-0.28*t)); g.rect(0,y,width,2); }
    // grain speckle (seeded, static)
    for (let s=0;s<Math.min(700, width*0.9);s++){
      const rx = (Math.sin(s*91.7)*0.5+0.5)*width;
      const ry = (Math.sin(s*57.3)*0.5+0.5)*gh;
      const d = (Math.sin(s*12.9)*0.5+0.5);
      g.fill(base[0], base[1]*0.7, base[2]*(0.6+0.4*d), 22);
      g.rect(rx, ry, 1.6, 1.6);
    }
  }
  S.ground = g; S.gy0 = gy0;
}
if (S.ground) { push(); tint(0,0,100, chalk?70:sil?85:80); image(S.ground, 0, S.gy0); noTint(); pop(); }

// ---- build list ----
const list = [];
for (let i=0;i<N;i++){
  const off = i/N;
  let ph = (off + globalScroll) % 1; if (ph<0) ph+=1;
  const dep = .72 + .5*fr(i+5);
  const px = -M + ph*spanW;
  const hgt = u*0.22*P.scale*dep;
  const py = P.y*height + (dep-1)*u*0.05;
  list.push({i,off,px,py,hgt,dep,sp:speciesFor(i)});
}
list.sort((a,b)=>a.dep-b.dep);

function ink(role, hue){
  noStroke();
  if (chalk){ noFill(); stroke(role==='eye'?0:role==='detail'?(hue+20)%360:0, 0, role==='eye'?100:88, 82); strokeWeight(Math.max(1.1, u*0.0018)); return; }
  if (sil){ fill(((P.hue%360)+360)%360, 30, 11); return; }
  if (wood){
    if (role==='eye') fill(0,0,96);
    else if (role==='detail') fill(hue,30,20);
    else fill(hue, 26, 14);
    return;
  }
  if (st==='riso'){
    if (role==='body') fill(hue,55,86,92);
    else if (role==='detail') fill((hue+18)%360,60,70,90);
    else if (role==='eye') fill(hue,60,20,95);
    else fill(hue,50,80,92);
    return;
  }
  // storybook gouache
  if (role==='body') fill(hue, 46, 74);
  else if (role==='detail') fill(hue, 54, 54);
  else if (role==='eye') fill(hue, 70, 16);
  else if (role==='light') fill(hue, 28, 88);
  else fill(hue, 44, 70);
}

// generic leg pair with alternating walk
function legs(hgt, bw, phB, sp, hue, legLift){
  const sw = Math.sin(phB*PI);
  const back = sp==='elephant'?4:2;
  ink('detail', hue);
  const lw = sp==='elephant'? bw*0.16 : bw*0.09;
  const legY = -hgt*0.02;
  const spread = sp==='elephant'? bw*0.3 : bw*0.26;
  // front-back pairs simplified to two visible legs with opposite phase
  for (let s=-1;s<=1;s+=2){
    const lift = (s>0? Math.max(0,sw): Math.max(0,-sw)) * legLift * hgt*0.08;
    push(); translate(s*spread, legY - lift);
      if (wood||chalk||sil){ rect(-lw*0.5, -hgt*0.16, lw, hgt*0.18); }
      else { rect(-lw*0.5, -hgt*0.16, lw, hgt*0.18, lw*0.3); }
      if (!sil&&!chalk){ ink('detail',hue); ellipse(0,-hgt*0.005, lw*1.5, lw*0.9); }
    pop();
    ink('detail', hue);
  }
}

function drawAnimal(a, phB, stomp){
  const hgt = a.hgt;
  const hue = hueFor(a.sp, a.i);
  const sw = Math.sin(phB*PI);
  const bw = hgt*0.7;

  // silhouette drop shadow
  if (!chalk){ noStroke(); fill(0,0,0, sil?24:16); ellipse(a.px, a.py+hgt*0.02, bw*1.1, hgt*0.07); }

  push();
  translate(a.px, a.py - stomp*hgt*0.04);
  rotate(Math.sin(phB*PI*2)*0.015*eAmp);

  if (a.sp === 'elephant'){
    legs(hgt, bw, phB, 'elephant', hue, 0.7);
    // body
    ink('body', hue);
    ellipse(0, -hgt*0.42, bw*1.05, hgt*0.6);
    // head
    push(); translate(-bw*0.5, -hgt*0.5);
      ink('body', hue); ellipse(0,0, bw*0.5, hgt*0.42);
      // ear
      ink('detail', hue); ellipse(bw*0.06,0, bw*0.34, hgt*0.34);
      // trunk swings
      ink('body', hue);
      const tr = Math.sin(phB*PI + a.i)*0.4*eAmp + stomp*0.3;
      push(); translate(-bw*0.16, hgt*0.02);
        beginShape();
        vertex(0,-hgt*0.06); vertex(-bw*0.06,-hgt*0.02);
        vertex(-bw*0.02 - tr*bw*0.2, hgt*0.16);
        vertex(-bw*0.12 - tr*bw*0.24, hgt*0.3);
        vertex(-bw*0.04 - tr*bw*0.24, hgt*0.31);
        vertex(bw*0.06 - tr*bw*0.2, hgt*0.16);
        vertex(bw*0.06,-hgt*0.02);
        endShape(CLOSE);
      pop();
      // eye
      ink('eye', hue); ellipse(-bw*0.02,-hgt*0.02, bw*0.07, bw*0.07);
      if (chalk){ ink('light',hue); }
    pop();
  } else if (a.sp === 'duck'){
    legs(hgt, bw*0.7, phB, 'duck', 30, 0.9);
    // body
    ink('body', hue);
    ellipse(hgt*0.02, -hgt*0.38, bw*0.9, hgt*0.5);
    // tail flip
    push(); translate(bw*0.42,-hgt*0.42); rotate(0.3+Math.sin(phB*PI)*0.1*eAmp);
      ink('detail',hue); triangle(0,-hgt*0.06,0,hgt*0.06,bw*0.24,0); pop();
    // neck+head
    push(); translate(-bw*0.34,-hgt*0.52); rotate(Math.sin(phB*PI*2)*0.06*eAmp);
      ink('body',hue); rect(-bw*0.06,0,bw*0.14,hgt*0.28, bw*0.05);
      ink('body',hue); ellipse(0,-hgt*0.02, bw*0.34, hgt*0.3);
      // bill
      ink('detail', 34); ellipse(-bw*0.2,hgt*0.0, bw*0.26, hgt*0.09);
      ink('eye',hue); ellipse(-bw*0.02,-hgt*0.05, bw*0.07,bw*0.07);
    pop();
  } else if (a.sp === 'dog'){
    legs(hgt, bw, phB, 'dog', hue, 1.0);
    ink('body', hue);
    ellipse(hgt*0.04, -hgt*0.4, bw*1.0, hgt*0.42);
    // tail wag
    push(); translate(bw*0.46,-hgt*0.5); rotate(-0.5 + Math.sin(phB*TAU + a.i)*0.5*(0.5+eAmp));
      ink('body',hue); rect(0,-bw*0.05, bw*0.34, bw*0.1, bw*0.05); pop();
    // head
    push(); translate(-bw*0.44,-hgt*0.52); rotate(Math.sin(phB*PI)*0.04*eAmp);
      ink('body',hue); ellipse(0,0, bw*0.42, hgt*0.36);
      // snout
      ink('detail',hue); ellipse(-bw*0.18,hgt*0.04, bw*0.26, hgt*0.18);
      // ear flops
      push(); rotate(0.2+Math.sin(phB*PI*2)*0.14*eAmp);
        ink('detail',hue); ellipse(bw*0.12,hgt*0.02, bw*0.14, hgt*0.26); pop();
      ink('eye',hue); ellipse(-bw*0.04,-hgt*0.04, bw*0.08,bw*0.08);
      ink('eye',24); ellipse(-bw*0.2,hgt*0.02, bw*0.06,bw*0.06);
    pop();
  } else { // cat
    legs(hgt, bw*0.9, phB, 'cat', hue, 0.9);
    ink('body', hue);
    ellipse(hgt*0.03, -hgt*0.4, bw*0.92, hgt*0.4);
    // arched tail
    push(); translate(bw*0.44,-hgt*0.46);
      ink('body',hue); noFill();
      if (!chalk){ strokeWeight(bw*0.12); stroke(chalk?0:hue, sil?30:46, sil?11:70, sil?100:100); }
      const tw = Math.sin(phB*TAU + a.i)*0.3*(0.4+eAmp);
      beginShape(); vertex(0,0); vertex(bw*0.18, -hgt*0.1); vertex(bw*0.28+tw*bw*0.2, -hgt*0.28); vertex(bw*0.16+tw*bw*0.3,-hgt*0.4); endShape();
      noStroke();
    pop();
    // head
    push(); translate(-bw*0.4,-hgt*0.5); rotate(Math.sin(phB*PI)*0.03*eAmp);
      ink('body',hue); ellipse(0,0, bw*0.4, hgt*0.34);
      // ears (triangles)
      ink('body',hue);
      triangle(-bw*0.12,-hgt*0.14,-bw*0.02,-hgt*0.14,-bw*0.08,-hgt*0.3);
      triangle(bw*0.02,-hgt*0.14,bw*0.12,-hgt*0.14,bw*0.08,-hgt*0.3);
      ink('eye',hue); ellipse(-bw*0.08,-hgt*0.02,bw*0.07,bw*0.09); ellipse(bw*0.06,-hgt*0.02,bw*0.07,bw*0.09);
      ink('detail',14); ellipse(-bw*0.01,hgt*0.06,bw*0.06,bw*0.05);
    pop();
  }

  pop();
}

for (let k=0;k<list.length;k++){
  const a = list[k];
  const phB = bt + a.off*4 + fr(a.i+9)*2;
  const stomp = stompDip * (0.6 + 0.4*Math.sin(phB*PI));
  drawAnimal(a, phB, stomp);
}

// dust puffs on collective stomp
if (!chalk && stompDip > 0.15){
  noStroke();
  for (let k=0;k<list.length;k+=2){
    const a = list[k];
    const pf = stompDip;
    fill(38, 22, 80, 30*pf);
    ellipse(a.px, a.py + a.hgt*0.02, a.hgt*(0.4+pf*0.5), a.hgt*0.12*pf);
  }
}

// ambient float motes / pollen (density)
if (P.density > 0.02){
  const n = Math.round(P.density*22);
  noStroke();
  for (let i=0;i<n;i++){
    const drift = (K.t*(0.08+fr(i+50)*0.12) + fr(i+70)) % 1;
    const fx = ((fr(i+90) + globalScroll*0.4)%1)*width;
    const fyv = ((drift + fr(i+110))%1)*u*0.7 + (P.y*height - u*0.62);
    const tw = 0.5 + 0.5*Math.sin(K.t*2.4 + i);
    fill(chalk?0:46, chalk?0:34, chalk?96:98, (10+18*tw)*(0.4+0.6*P.density));
    ellipse(fx, fyv, u*0.0035*(0.8+tw), u*0.0035*(0.8+tw));
  }
}
